def transform(grid):
    n = len(grid[0])
    center = next(i for i, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            lo, hi = center - r, center + r
            out[r][lo] = 2
            out[r][hi] = 2
        else:
            lo, hi = 0, n - 1
        for c in range(lo, hi + 1):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out
